const STY = (bg) => `position:absolute;left:70px;width:800px;height:180px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#ffffff;font-family:inherit;font-weight:800;line-height:1.1;font-size:46px;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;">GITHUB RELEASE<br><span style="font-size:30px;font-weight:600;margin-top:8px;opacity:0.9">SPECS AND CODE</span></div>
  <div id="c1" style="${STY(B2)}top:430px;">ONGOING<br><span style="font-size:30px;font-weight:600;margin-top:8px;opacity:0.9">RESEARCH PHASE</span></div>
  <div id="c2" style="${STY(B1)}top:780px;">NO PRODUCTION<br><span style="font-size:30px;font-weight:600;margin-top:8px;opacity:0.9">ROLLOUT PLANS</span></div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:8;stroke-linecap:round;">
    <path id="l0" d="M470 260 L470 430" />
    <path id="l1" d="M470 610 L470 780" />
  </svg>
`;

const items = [0, 1, 2].map(i => root.querySelector('#c' + i));
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  el.style.opacity = 0;
  return { el, len };
});

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Cards Entrance
  items.forEach((el, i) => {
    // Timing: 0, 1.2, 2.4 seconds offset
    const s = spr(tf, i * 1.2, 0.88, 7);
    el.style.opacity = clamp(s * 1.5);
    const y = lerp(60, 0, E_OUT(clamp(s)));
    const scale = lerp(0.85, 1, E_OUT(clamp(s)));
    el.style.transform = `translateY(${y}px) scale(${scale})`;
  });

  // Lines Drawing
  lines.forEach((l, i) => {
    // Lines start shortly after the previous card appears
    const s = spr(tf, 0.8 + i * 1.2, 0.95, 6);
    l.el.style.strokeDashoffset = l.len * (1 - clamp(s));
    l.el.style.opacity = clamp(s) * 0.3;
  });

  // Progress state for the entire group (subtle vertical drift)
  const masterY = lerp(20, 0, E_OUT(p * 2));
  root.style.transform = `translateY(${masterY}px)`;
}
